# Extract the UI subset from the pinned, unmodified dnSpy sources in this directory.
# No network access is needed. See NOTICE.md for upstream attribution and adaptations.
$ErrorActionPreference = 'Stop'
$xamlNamespace = 'http://schemas.microsoft.com/winfx/2006/xaml'
$presentationNamespace = 'http://schemas.microsoft.com/winfx/2006/xaml/presentation'
$source = [xml][IO.File]::ReadAllText((Join-Path $PSScriptRoot 'wpf.styles.templates.xaml'))
$selectedKeys = @(
    'BaseButtonStyle', '{x:Type Button}', '{x:Type ToggleButton}', '{x:Type RepeatButton}',
    '{x:Type TabControl}', '{x:Type TabItem}', '{x:Type ToolTip}',
    'ToolBarMainPanelBorderStyle', '{x:Static ToolBar.SeparatorStyleKey}',
    '{x:Static ToolBar.ButtonStyleKey}', '{x:Type ToolBar}',
    'ComboBoxEditableTextBox', 'ToolBarComboBoxTransparentButtonStyle',
    '{x:Static ToolBar.ComboBoxStyleKey}', '{x:Type ComboBoxItem}',
    '{x:Type TextBoxBase}', '{x:Type TextBox}',
    '{x:Static GridView.GridViewScrollViewerStyleKey}', 'GridViewColumnHeaderGripper',
    '{x:Type GridViewColumnHeader}', '{x:Static GridView.GridViewStyleKey}',
    'ListViewItemFocusVisual', '{x:Static GridView.GridViewItemContainerStyleKey}',
    '{x:Type ListView}', '{x:Type ListViewItem}',
    'ExpandCollapseToggleStyle',
    'ScrollBarButton', 'ScrollBarThumb', 'HorizontalScrollBarPageButton',
    'VerticalScrollBarPageButton', '{x:Type ScrollBar}', '{x:Type ScrollViewer}',
    '{x:Type ctrls:TabButton}', 'FileTabGroupTabControlStyle', 'FileTabGroupTabItemStyle'
)
$dictionary = [xml]@'
<ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
                    xmlns:theme="clr-namespace:Microsoft.Windows.Themes;assembly=PresentationFramework.Aero"
                    xmlns:mvvm="clr-namespace:AirCard.Controls"
                    xmlns:ctrls="clr-namespace:dnSpy.Controls">
  <!-- Adapted from dnSpy, copyright (C) 2014-2019 de4dot@gmail.com; GPL-3.0-or-later.
       Generated by ThirdParty/dnSpy/Import-Theme.ps1. See ThirdParty/dnSpy/NOTICE.md. -->
  <SolidColorBrush x:Key="TransparentBrush" Color="Transparent" />
</ResourceDictionary>
'@
foreach ($node in $source.DocumentElement.ChildNodes) {
    if ($node.NodeType -ne [Xml.XmlNodeType]::Element) { continue }
    $key = $node.GetAttribute('Key', $xamlNamespace)
    if (-not $key -and $node.LocalName -eq 'Style') { $key = $node.GetAttribute('TargetType') }
    if ($selectedKeys -notcontains $key) { continue }
    $copy = $dictionary.ImportNode($node, $true)
    foreach ($comment in @($copy.SelectNodes('.//comment()'))) { $comment.ParentNode.RemoveChild($comment) | Out-Null }
    # The fixed workspace has no dnSpy document manager, drag/drop service or image service.
    foreach ($element in @($copy.SelectNodes('.//*'))) {
        foreach ($attribute in @($element.Attributes)) {
            if ($attribute.LocalName -eq 'IsDraggableAP.IsDraggable') { $element.RemoveAttributeNode($attribute) | Out-Null }
        }
    }
    foreach ($setter in @($copy.SelectNodes('.//*[local-name()="Setter"]'))) {
        if ($setter.GetAttribute('Property') -eq 'img:DsImage.BackgroundBrush' -or
            $setter.GetAttribute('Value') -like '{Binding HasOpenedDoc,*') {
            $setter.ParentNode.RemoveChild($setter) | Out-Null
        }
    }
    if ($key -eq 'FileTabGroupTabControlStyle') {
        foreach ($trigger in $copy.SelectNodes('.//*[local-name()="DataTrigger"]')) {
            $trigger.SetAttribute('Binding', '{Binding IsActive, RelativeSource={RelativeSource AncestorType={x:Type Window}}}')
            $trigger.SetAttribute('Value', [string]($trigger.GetAttribute('Value') -eq 'Active'))
        }
    }
    if ($key -eq 'FileTabGroupTabItemStyle') {
        # Let the local workspace style supply a subtle resting fill and outline.
        $tabBorder = $copy.SelectSingleNode('.//*[local-name()="Border" and @Name="Border"]')
        $tabBorder.SetAttribute('Background', '{TemplateBinding Background}')
        $tabBorder.SetAttribute('BorderBrush', '{TemplateBinding BorderBrush}')
        $tabBorder.SetAttribute('BorderThickness', '{TemplateBinding BorderThickness}')
        foreach ($element in $copy.SelectNodes('.//*')) {
            foreach ($attribute in @($element.Attributes)) {
                $value = $attribute.Value
                if ($value -eq '{Binding Header}') { $attribute.Value = '{TemplateBinding Header}' }
                elseif ($value -eq '{Binding ToolTip}') { $attribute.Value = '{TemplateBinding ToolTip}' }
                elseif ($value -match '^\{Binding (Path=)?IsSelected\}$') {
                    $attribute.Value = '{Binding IsSelected, RelativeSource={RelativeSource Self}}'
                }
                elseif ($value -match '^\{Binding (Path=)?IsActive\}$') {
                    $attribute.Value = '{Binding IsActive, RelativeSource={RelativeSource AncestorType={x:Type Window}}}'
                }
            }
            if ($element.LocalName -eq 'TabButton') {
                $element.RemoveAttribute('Command')
                $element.SetAttribute('Visibility', 'Collapsed')
                $element.SetAttribute('ToolTip', 'Close')
            }
        }
        # Selected tabs must remain keyboard focusable in this standalone WPF workspace.
        foreach ($setter in @($copy.SelectNodes('.//*[local-name()="Setter"]'))) {
            if ($setter.GetAttribute('Property') -eq 'UIElement.Focusable') { $setter.ParentNode.RemoveChild($setter) | Out-Null }
        }
    }
    if ($key -eq '{x:Type ScrollViewer}') {
        # Upstream swapped these names. WPF wires scrolling through these exact template parts.
        foreach ($bar in $copy.SelectNodes('.//*[local-name()="ScrollBar"]')) {
            $name = if ($bar.GetAttribute('Orientation') -eq 'Horizontal') { 'PART_HorizontalScrollBar' } else { 'PART_VerticalScrollBar' }
            $bar.SetAttribute('Name', $xamlNamespace, $name) | Out-Null
        }
    }
    [void]$dictionary.DocumentElement.AppendChild($copy)
}

# Resolve dnSpy's resource names using its own ColorInfos definitions, not guessed name/color pairs.
$required = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
foreach ($match in [regex]::Matches($dictionary.OuterXml, '\{DynamicResource ([\w.]+)\}')) { [void]$required.Add($match.Groups[1].Value) }
foreach ($name in @('EnvironmentBackground', 'EnvironmentForeground', 'EnvironmentToolWindow',
    'EnvironmentToolWindowBorder', 'SystemColorsGrayText', 'EnvironmentFileTabSelectedBorder',
    'StatusBarDebuggingBackground', 'StatusBarDebuggingForeground',
    'TreeViewBackground', 'TreeViewForeground', 'TreeViewBorder',
    'TreeViewItemSelectedBackground', 'TreeViewItemSelectedForeground',
    'TreeViewItemMouseOverTextBackground', 'TreeViewItemMouseOverForeground')) { [void]$required.Add($name) }
[void]$required.Remove('TransparentBrush')
foreach ($name in @('DialogWindowBackground', 'DialogWindowActiveDefaultBorder', 'DialogWindowInactiveBorder',
    'DialogWindowActiveCaption', 'DialogWindowActiveCaptionText', 'DialogWindowInactiveCaption', 'DialogWindowInactiveCaptionText',
    'EnvironmentMainWindowButtonActiveGlyph', 'EnvironmentMainWindowButtonHoverActive', 'EnvironmentMainWindowButtonHoverActiveGlyph',
    'EnvironmentMainWindowButtonDown', 'EnvironmentMainWindowButtonDownGlyph')) { [void]$required.Add($name) }
foreach ($name in @('EnvironmentMainWindowActiveDefaultBorder', 'EnvironmentMainWindowInactiveBorder',
    'EnvironmentMainWindowActiveCaption', 'EnvironmentMainWindowActiveCaptionText',
    'EnvironmentMainWindowInactiveCaption', 'EnvironmentMainWindowInactiveCaptionText')) { [void]$required.Add($name) }
$theme = [xml][IO.File]::ReadAllText((Join-Path $PSScriptRoot 'dark.dntheme'))
$colors = @{}
foreach ($color in $theme.theme.colors.color) { $colors[$color.name] = $color }
$definitions = [IO.File]::ReadAllText((Join-Path $PSScriptRoot 'ColorInfos.cs'))
$resources = @{}
$entries = [regex]::Matches($definitions, '(?ms)new (?<kind>Brush|Color|LinearGradient)ColorInfo\(ColorType\.(?<name>\w+),(?<args>.*?)\)\s*\{(?<body>.*?)^\s*\},')
foreach ($entry in $entries) {
    $body = $entry.Groups['body'].Value
    $themeColor = $colors[$entry.Groups['name'].Value]
    $values = @{}
    foreach ($field in @(@('Foreground','fg'), @('Background','bg'), @('Color3','color3'), @('Color4','color4'))) {
        $value = if ($themeColor) { $themeColor.GetAttribute($field[1]) } else { '' }
        if (-not $value) {
            $default = [regex]::Match($body, ('Default{0}\s*=\s*"([^"]+)"' -f $field[0]))
            if ($default.Success) { $value = $default.Groups[1].Value }
        }
        $values[$field[0]] = $value
    }
    if ($entry.Groups['kind'].Value -in @('Brush', 'Color')) {
        foreach ($field in @('Foreground', 'Background')) {
            $mapping = [regex]::Match($body, ($field + 'ResourceKey\s*=\s*"([^"]+)"'))
            if (-not $mapping.Success -or -not $required.Contains($mapping.Groups[1].Value)) { continue }
            $name = $mapping.Groups[1].Value
            if (-not $values[$field]) { throw "Missing theme color for $name" }
            $resources[$name] = if ($entry.Groups['kind'].Value -eq 'Color') {
                '<Color x:Key="{0}">{1}</Color>' -f $name, $values[$field]
            } else {
                '<SolidColorBrush x:Key="{0}" Color="{1}" />' -f $name, $values[$field]
            }
        }
    } else {
        $mapping = [regex]::Match($body, '(?m)^\s*ResourceKey\s*=\s*"([^"]+)"')
        if (-not $mapping.Success -or -not $required.Contains($mapping.Groups[1].Value)) { continue }
        $name = $mapping.Groups[1].Value
        $args = $entry.Groups['args'].Value
        $point = [regex]::Match($args, 'new Point\(([^)]+)\)')
        $offsets = ([regex]::Match($args, '"[^"\r\n]*",\s*([\d., ]+)$')).Groups[1].Value.Split(',')
        $fields = @('Foreground', 'Background', 'Color3', 'Color4')
        $stops = for ($i = 0; $i -lt $offsets.Count; $i++) {
            if (-not $values[$fields[$i]]) { throw "Missing gradient color for $name" }
            '<GradientStop Color="{0}" Offset="{1}" />' -f $values[$fields[$i]], $offsets[$i].Trim()
        }
        $resources[$name] = '<LinearGradientBrush x:Key="{0}" StartPoint="0,0" EndPoint="{1}">{2}</LinearGradientBrush>' -f $name, $point.Groups[1].Value, ($stops -join '')
    }
}
foreach ($name in $required) { if (-not $resources.ContainsKey($name)) { throw "Unresolved dnSpy resource: $name" } }
$palette = [xml]('<ResourceDictionary xmlns="' + $presentationNamespace + '" xmlns:x="' + $xamlNamespace + '">' +
    '<!-- Generated from dnSpy dark.dntheme and ColorInfos.cs; GPL-3.0-or-later. See ThirdParty/dnSpy/NOTICE.md. -->' +
    (($resources.Keys | Sort-Object | ForEach-Object { $resources[$_] }) -join "`n") + '</ResourceDictionary>')
$output = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..\Themes\dnSpy'))
[void][IO.Directory]::CreateDirectory($output)
foreach ($pair in @(@('Controls.xaml', $dictionary), @('Dark.xaml', $palette))) {
    $settings = [Xml.XmlWriterSettings]::new()
    $settings.Indent = $true
    $settings.Encoding = [Text.UTF8Encoding]::new($false)
    $writer = [Xml.XmlWriter]::Create((Join-Path $output $pair[0]), $settings)
    try { $pair[1].Save($writer) } finally { $writer.Dispose() }
}
Write-Output "Imported $($selectedKeys.Count) dnSpy styles and $($resources.Count) theme resources."
